typedef struct Node { NodeKind kind; struct Node *kids[2]; int nkids; } Node;
typedef struct { bool (*match)(const Node *); void (*rewrite)(Node **); } Rule;
static const Rule RULES[] = { { m_add_zero, r_drop_zero }, { m_not_not, r_strip_not } };
#define NRULES (sizeof RULES / sizeof RULES[0])

static Node *apply(Node *n) {                    /* engine owns the walk */
    if (!n) return n;
    for (int i = 0; i < n->nkids; i++) n->kids[i] = apply(n->kids[i]);
    for (size_t r = 0; r < NRULES; r++)
        if (RULES[r].match(n)) { RULES[r].rewrite(&n); break; }
    return n;
}
